const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const nyc = ee.Geometry.Point([-74.0060, 40.7128]);
  const date2024 = '2024-06-24';
  const date2025 = '2025-06-24';

  // 2. Data Acquisition & Check
  // Using ERA5-Land hourly data for temperature (more reliable than MODIS for specific dates)
  const col2024 = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(date2024, '2024-06-25')
    .filterBounds(nyc)
    .select('temperature_2m');

  const col2025 = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(date2025, '2025-06-25')
    .filterBounds(nyc)
    .select('temperature_2m');

  const size2024 = await col2024.size().getInfo();
  const size2025 = await col2025.size().getInfo();

  console.log(`2024 Images: ${size2024}`);
  console.log(`2025 Images: ${size2025}`);

  // Check if 2025 data exists (it shouldn't - future date)
  if (size2025 === 0) {
    console.log('No data available for June 24, 2025 (future date).');
    console.log('<answer>C1</answer>');
    return;
  }

  // Check if 2024 data exists
  if (size2024 === 0) {
    console.log('No data available for June 24, 2024.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Get maximum temperature for each day
  const max2024 = col2024.max();
  const max2025 = col2025.max();

  // 4. Calculation
  const temp2024 = await max2024.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: nyc,
    scale: 11132,
    maxPixels: 1e9
  }).get('temperature_2m').getInfo();

  const temp2025 = await max2025.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: nyc,
    scale: 11132,
    maxPixels: 1e9
  }).get('temperature_2m').getInfo();

  // Convert from Kelvin to Celsius
  const temp2024C = temp2024 ? temp2024 - 273.15 : null;
  const temp2025C = temp2025 ? temp2025 - 273.15 : null;

  // 5. Validation & Final Answer
  if (temp2024C === null || temp2025C === null) {
    console.log('Temperature calculation failed.');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`2024 Max Temp: ${temp2024C.toFixed(2)}C`);
  console.log(`2025 Max Temp: ${temp2025C.toFixed(2)}C`);

  if (temp2025C > temp2024C) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
